def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    colors={v for row in grid for v in row if v!=grid[0][0]}
    segments=[]
    for color in colors:
        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        for i,(r1,c1) in enumerate(pts):
            for r2,c2 in pts[i+1:]:
                dr,dc=r2-r1,c2-c1
                if abs(dr)==abs(dc) and dr!=0:
                    sr=1 if dr>0 else -1
                    sc=1 if dc>0 else -1
                    cells=[(r1+k*sr,c1+k*sc) for k in range(abs(dr)+1)]
                    segments.append((color,sr,sc,cells))
                    for r,c in cells: out[r][c]=color
    # A contrasting marker lying on a drawn diagonal extends perpendicular to the grid edges.
    for marker_color in colors:
        for r in range(h):
            for c in range(w):
                if grid[r][c]!=marker_color: continue
                for line_color,sr,sc,cells in segments:
                    if line_color==marker_color or (r,c) not in cells: continue
                    # the diagonal through this marker has the opposite slope
                    er=1 if sr==sc else 1
                    ec=-1 if sr==sc else 1
                    # trace both directions to the grid boundary
                    rr,cc=r,c
                    while 0<=rr<h and 0<=cc<w:
                        out[rr][cc]=marker_color; rr-=er; cc-=ec
                    rr,cc=r+er,c+ec
                    while 0<=rr<h and 0<=cc<w:
                        out[rr][cc]=marker_color; rr+=er; cc+=ec
    return out

