    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    out = [row[:] for row in grid]
    colors = {value for row in grid for value in row if value != background}
    segments = []

    # Join same-color markers when they lie on a 45-degree diagonal.
    for color in colors:
        points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if dr and abs(dr) == abs(dc):
                    sr = 1 if dr > 0 else -1
                    sc = 1 if dc > 0 else -1
                    cells = [(r1 + k * sr, c1 + k * sc) for k in range(abs(dr) + 1)]
                    segments.append((color, sr, sc, cells))

    # Longer strokes take precedence where strokes of different colors overlap.
    for color, sr, sc, cells in sorted(segments, key=lambda item: -len(item[3])):
        for r, c in cells:
            if grid[r][c] == background and out[r][c] == background:
                out[r][c] = color

    # A contrasting marker on a diagonal stroke extends perpendicularly to the grid edges.
    for marker_color in colors:
        for r in range(h):
            for c in range(w):
                if grid[r][c] != marker_color:
                    continue
                for line_color, sr, sc, cells in segments:
                    if line_color == marker_color or (r, c) not in cells:
                        continue
                    er, ec = (1, -1) if sr == sc else (1, 1)
                    rr, cc = r - er, c - ec
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] == background:
                            out[rr][cc] = marker_color
                        rr -= er
                        cc -= ec
                    rr, cc = r + er, c + ec
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] == background:
                            out[rr][cc] = marker_color
                        rr += er
                        cc += ec
    return out
